Input: {"question": "When was Dunville incorporated as a town?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0200-ebf13065ba5b:d00", "start": 0, "end": 10, "text": "years ago."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0200-ebf13065ba5b:d00", "start": 11, "end": 287, "text": "There is an impassable dam at Dunnville which regulates the level of the Grand River at Port Maitland which, in the 19th century, also helped regulate the level of the Welland Canal (from 1829 until 1887 when the third canal began to intake its water directly from Lake Erie)."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0200-ebf13065ba5b:d00", "start": 288, "end": 363, "text": "Dunnville was incorporated as a village in 1860 and then as a town in 1900."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0200-ebf13065ba5b:d00", "start": 364, "end": 520, "text": "In 1974, the town amalgamated with the townships of Dunn, Canborough, Moulton and Sherbrooke when the Regional Municipality of Haldimand-Norfolk was formed."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0200-ebf13065ba5b:d00", "start": 521, "end": 601, "text": "In 2001, Dunnville and all other municipalities within the region were dissolved"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0200-ebf13065ba5b:d01", "start": 0, "end": 32, "text": "the Welland `` feeder '' canal ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0200-ebf13065ba5b:d01", "start": 33, "end": 114, "text": "The town was once home to several water-powered mills and a bustling canal port ."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0200-ebf13065ba5b:d01", "start": 115, "end": 247, "text": "However , the feeder canal closed in the late 1880s , and the last mill was replaced with a condominium complex about a decade ago ."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0200-ebf13065ba5b:d01", "start": 248, "end": 336, "text": "An impassable dam at Dunnville regulates the level of the Grand River at Port Maitland ."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0200-ebf13065ba5b:d01", "start": 337, "end": 421, "text": "In the 19th century , this dam also helped regulate the level of the Welland Canal ."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0200-ebf13065ba5b:d01", "start": 422, "end": 498, "text": "Dunnville was incorporated as a village in 1860 and then as a town in 1900 ."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0200-ebf13065ba5b:d01", "start": 499, "end": 508, "text": "In 1974 ,"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0200-ebf13065ba5b:d02", "start": 0, "end": 98, "text": "Dunville, Newfoundland and Labrador Dunville was earlier called Northeast or North East Placentia."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0200-ebf13065ba5b:d02", "start": 99, "end": 173, "text": "The name was formed from \"Dunphy's Village\" a part of Northeast Placentia."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0200-ebf13065ba5b:d02", "start": 174, "end": 257, "text": "It is a community that makes up the north-eastern section of the Town of Placentia."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0200-ebf13065ba5b:d02", "start": 258, "end": 353, "text": "It stretches approximately 8km along the northern shore of the North-East Arm of Placentia Bay."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0200-ebf13065ba5b:d02", "start": 354, "end": 440, "text": "The Post Office was established in 1895 and the first Post Master was Joachim Connors."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0200-ebf13065ba5b:d02", "start": 441, "end": 494, "text": "Dunville was incorporated as a town on June 11, 1963."}, "D3S7": {"document_number": 3, "doc_id": "ramdocs-0200-ebf13065ba5b:d02", "start": 495, "end": 533, "text": "By 1966, it had a population of 1,606."}, "D3S8": {"document_number": 3, "doc_id": "ramdocs-0200-ebf13065ba5b:d02", "start": 534, "end": 613, "text": "Along with Freshwater, Argentia, and Jerseyside, it became part of Placentia in"}}, "original_cards": [{"doc_id": "ramdocs-0200-ebf13065ba5b:d00", "card_id": "ramdocs-0200-ebf13065ba5b:d00:c0", "entity": "Dunnville", "scope": "incorporation as a town", "claim": "Dunnville was incorporated as a town in 1900.", "answer": "1900", "quote": "Dunnville was incorporated as a village in 1860 and then as a town in 1900.", "original_document_number": 1}, {"doc_id": "ramdocs-0200-ebf13065ba5b:d01", "card_id": "ramdocs-0200-ebf13065ba5b:d01:c0", "entity": "Dunnville", "scope": "incorporation as a town", "claim": "Dunnville was incorporated as a town in 1900.", "answer": "1900", "quote": "Dunnville was incorporated as a village in 1860 and then as a town in 1900 .", "original_document_number": 2}, {"doc_id": "ramdocs-0200-ebf13065ba5b:d02", "card_id": "ramdocs-0200-ebf13065ba5b:d02:c0", "entity": "Dunville", "scope": "incorporation date", "claim": "Dunville was incorporated as a town on June 11, 1963.", "answer": "June 11, 1963", "quote": "Dunville was incorporated as a town on June 11, 1963.", "original_document_number": 3}], "current_answers": ["1900", "June 11, 1963"], "candidate_answers": [{"candidate_id": "R0", "answer": "1900", "origin": "initial"}, {"candidate_id": "R1", "answer": "June 11, 1963", "origin": "initial"}], "requested_slot_hint": "other"}
